// TideWall 3D — Part I's level, the town and the beach: references to its parts (saved in the TideWall scene), the
// things that change per phase (picnic food, gas cans, the lighthouse), and where creatures go: the wall, any breach,
// and the powerplant behind it. Generated by WorldBuilder (TideWall → Rebuild World In Scene); edit it in Unity.
using System;
using Random = UnityEngine.Random;
using System.Collections.Generic;
using UnityEngine;

namespace TideWall
{
    public class World : Level
    {
        public Wall wall;
        public PowerPlant plant;
        public Transform lighthouseLamp;
        public Model keep;
        public Vendor chef, fishmonger;
        public Light lighthouseBeam;
        [NonSerialized] public readonly List<GameObject> phaseLoot = new(); // food and gas cans placed this morning

        /// <summary>A fresh run: hit points and lines from the data (so tuning the data needs no scene changes).</summary>
        public override void Init(GameDatabase db)
        {
            wall.Init(db.wallSegmentHp);
            plant.Init(db.plantMaxHp);
            chef.Init(db.chefLines);
            fishmonger.Init(db.fishmongerLines);
        }

        public override void OnPhaseStart(PhaseDefinition p, int extraGasCans)
        {
            var db = GameManager.I.DB;
            if (p.spawnFood)
            {
                // Picnic leftovers: free food scattered around the beach towels.
                var beachFoods = db.foods.FindAll(f => f.spawnsOnBeach);
                int n = Random.Range(5, 9);
                for (int i = 0; i < n && beachFoods.Count > 0; i++)
                    phaseLoot.Add(FoodPickup.Spawn(beachFoods[Random.Range(0, beachFoods.Count)], RandomBeachSpot(4, 30)).gameObject);
            }
            if (p.spawnGasCans)
            {
                int n = db.baseGasCans + extraGasCans;
                for (int i = 0; i < n; i++) phaseLoot.Add(GasCan.Spawn(RandomBeachSpot(3, 32)).gameObject);
            }
            phaseLoot.RemoveAll(g => g == null);
        }

        public static Vector3 RandomBeachSpot(float zMin, float zMax) =>
            new(Random.Range(-Arena.WallHalfLength + 2, Arena.WallHalfLength - 2), 0, Random.Range(zMin, zMax));

        protected override void OnNightLights(float torches01)
        {
            if (lighthouseBeam) lighthouseBeam.intensity = 60 * torches01;
        }

        public override Vector3 SpawnPoint(int index) => new(-3 + index * 2, 0, -7);

        public override Vector3 FlyerTarget(Vector3 from) => plant.transform.position + Vector3.up * 3;

        public override string BuildRule(Vector3 spot, float radius)
        {
            if (spot.z > Arena.ShoreZ - 1) return "Too close to the sea";
            if (Mathf.Abs(spot.z - Arena.WallZ) < radius + .9f) return "Too close to the wall";
            if (spot.z < Arena.TownMinZ + 1 || Mathf.Abs(spot.x) > Arena.BoundX - 1) return "Out of bounds";
            var toPlant = Arena.PlantPos - spot; toPlant.y = 0;
            if (toPlant.magnitude < Arena.PlantRadius + radius) return "Too close to the powerplant";
            return null;
        }

        public override string StatusLine()
        {
            int breached = wall.BreachCount, sections = wall.Sections.Count;
            return $"Powerplant {Mathf.CeilToInt(plant.Hp)}/{Mathf.RoundToInt(plant.MaxHp)} · Wall {sections - breached}/{sections}" +
                   (breached > 0 ? $" <color=#fca5a5>({breached} breached)</color>" : "");
        }

        public override float StatusFraction() => plant.Fraction;

        /// <summary>Where a creature at `from` should head when it isn't chasing a player:
        /// through the nearest breach if there is one (and on to the powerplant), else to the wall in front of it.</summary>
        public override Vector3 Goal(Vector3 from, float radius, out GoalKind kind)
        {
            if (Arena.Inside(from)) { kind = GoalKind.Plant; return plant.Approach(from, radius); }
            if (wall.NearestBreach(from.x, out float bx) && Mathf.Abs(bx - from.x) < 40)
            {
                kind = GoalKind.Breach;
                // Line up with the gap first, then walk through it.
                return Mathf.Abs(from.x - bx) > .8f && from.z > Arena.WallFront + radius + 1.5f
                    ? new Vector3(bx, 0, Arena.WallFront + radius + 1)
                    : new Vector3(bx, 0, Arena.WallZ - 2.5f);
            }
            kind = GoalKind.Wall;
            return Arena.WallTarget(from.x, radius);
        }

        protected override void Update()
        {
            base.Update();
            if (lighthouseLamp) lighthouseLamp.rotation = Quaternion.Euler(12, Time.time * 40, 0);
        }
    }
}
